      "content": "import { expect, test } from 'bun:test';
import { DomainError } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { Task } from '../domain/task';
import { TaskCompleted, TaskCreated } from '../domain/task.events';

test(covers(['method:Task.complete'], 'conclui tarefa pending e registra TaskCompleted preservando eventos anteriores'), () => {
  const task = Task.create('task-complete-1', 'Minha tarefa');
  expect(task.status).toBe('pending');

  task.complete();

  expect(task.status).toBe('completed');
  expect(task.id).toBe('task-complete-1');
  expect(task.title).toBe('Minha tarefa');
  const events = task.pullEvents();
  expect(events).toHaveLength(2);
  expect(events[0]).toBeInstanceOf(TaskCreated);
  expect(events[1]).toBeInstanceOf(TaskCompleted);
  expect(events[1]!.payload).toEqual({ taskId: 'task-complete-1' });
  expect(task.pullEvents()).toEqual([]);
});

test(covers([
  'method:Task.complete',
  'criterion:0001/conclusao',
], 'conclui uma vez e rejeita repetição com TASK_ALREADY_COMPLETED sem novo evento'), () => {
  const task = Task.create('task-complete-2', 'Outra tarefa');
  task.pullEvents();
  expect(task.status).toBe('pending');

  task.complete();

  expect(task.status).toBe('completed');
  const events = task.pullEvents();
  expect(events).toHaveLength(1);
  expect(events[0]).toBeInstanceOf(TaskCompleted);
  expect(events[0]!.payload).toEqual({ taskId: 'task-complete-2' });

  let failure: unknown;
  try {
    task.complete();
  } catch (error) {
    failure = error;
  }
  expect(failure).toBeInstanceOf(DomainError);
  expect((failure as DomainError).code).toBe('TASK_ALREADY_COMPLETED');
  expect(task.status).toBe('completed');
  expect(task.pullEvents()).toEqual([]);
});
